import { randomBytes } from 'node:crypto';
import { appendFileSync, chmodSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { defaultRuntimeHome } from './runtime-config.mjs';

const root = new URL('../', import.meta.url);
const target = new URL('.env', root);
if (existsSync(target)) {
  console.log('.env already exists; kept existing configuration.');
  const existing = readFileSync(target, 'utf8');
  // Upgrade only the local credentials generated by T01, preserving all other
  // settings. An external/custom database requires an explicit operator setup.
  if (!/^MIGRATION_DATABASE_URL=/m.test(existing)) {
    process.loadEnvFile(target);
    const url = process.env.DATABASE_URL ? new URL(process.env.DATABASE_URL) : null;
    if (url && ['127.0.0.1', 'localhost'].includes(url.hostname) &&
      decodeURIComponent(url.username) === process.env.POSTGRES_USER &&
      decodeURIComponent(url.password) === process.env.POSTGRES_PASSWORD &&
      url.pathname.slice(1) === process.env.POSTGRES_DB) {
      url.searchParams.set('schema', 'orai');
      const migrationUrl = url.toString();
      url.username = 'orai_app';
      url.password = randomBytes(24).toString('hex');
      const appUrl = url.toString();
      url.hostname = 'db'; url.port = '5432';
      const extra = '\nMIGRATION_DATABASE_URL=' + migrationUrl +
        '\nDATABASE_CONTAINER_URL=' + url.toString() + '\nDEMO_SEED_DATABASE=' + process.env.POSTGRES_DB + '\n';
      writeFileSync(target, existing.replace(/^DATABASE_URL=.*$/m, 'DATABASE_URL=' + appUrl) + extra, { mode: 0o600 });
      console.log('Separated the owned local runtime and migration credentials. Values were not printed.');
    }
  }
} else {
  const example = readFileSync(new URL('.env.example', root), 'utf8');
  const ownerPassword = randomBytes(24).toString('hex');
  const appPassword = randomBytes(24).toString('hex');
  writeFileSync(target, example.replaceAll('REPLACE_WITH_LOCAL_OWNER_PASSWORD', ownerPassword)
    .replaceAll('REPLACE_WITH_LOCAL_APP_PASSWORD', appPassword)
    .replaceAll('REPLACE_WITH_LOCAL_CSRF_SECRET', randomBytes(32).toString('base64url'))
    .replaceAll('REPLACE_WITH_LOCAL_AUTH_SECRET', randomBytes(32).toString('base64url')), { mode: 0o600, flag: 'wx' });
  console.log('Created local .env with a generated database password. Values were not printed.');
}
if (!/^CSRF_SIGNING_KEY=.+$/m.test(readFileSync(target, 'utf8'))) {
  process.loadEnvFile(target);
  let local = false;
  try { local = ['development', 'test'].includes(process.env.APP_ENV ?? '') && ['127.0.0.1', 'localhost', '[::1]'].includes(new URL(process.env.DATABASE_URL ?? '').hostname); } catch {}
  if (local) {
    const current = readFileSync(target, 'utf8');
    writeFileSync(target, current.replace(/^CSRF_SIGNING_KEY=.*\n?/m, '') + '\nCSRF_SIGNING_KEY=' + randomBytes(32).toString('base64url') + '\n', { mode: 0o600 });
    console.log('Added a stable random local CSRF key. Value was not printed.');
  }
}
{
  const current = readFileSync(target, 'utf8');
  const key = current.match(/^AUTH_SESSION_ENCRYPTION_KEY=(.*)$/m)?.[1];
  if (key === undefined || key === '' || key === 'REPLACE_WITH_LOCAL_AUTH_SECRET') {
    process.loadEnvFile(target);
    let ownedLocal = false;
    try {
      const runtime = new URL(process.env.DATABASE_URL ?? '');
      const owner = new URL(process.env.MIGRATION_DATABASE_URL ?? '');
      ownedLocal = ['development', 'test'].includes(process.env.APP_ENV ?? '') &&
        ['127.0.0.1', 'localhost', '[::1]'].includes(runtime.hostname) &&
        owner.hostname === runtime.hostname && owner.port === runtime.port &&
        owner.pathname === runtime.pathname && runtime.pathname === '/' + process.env.POSTGRES_DB &&
        decodeURIComponent(runtime.username) === 'orai_app' &&
        decodeURIComponent(owner.username) === process.env.POSTGRES_USER &&
        decodeURIComponent(owner.password) === process.env.POSTGRES_PASSWORD;
    } catch { /* Custom/external setups require operator configuration. */ }
    if (ownedLocal) {
      writeFileSync(target, current.replace(/^AUTH_SESSION_ENCRYPTION_KEY=.*\n?/m, '') +
        '\nAUTH_SESSION_ENCRYPTION_KEY=' + randomBytes(32).toString('base64url') + '\n', { mode: 0o600 });
      chmodSync(target, 0o600);
      console.log('Added a stable random local account encryption key. Value was not printed.');
    }
  }
}
if (process.platform === 'darwin' && !/^ORAI_RUNTIME_HOME=/m.test(readFileSync(target, 'utf8'))) {
  appendFileSync(target, `\nORAI_RUNTIME_HOME=${JSON.stringify(defaultRuntimeHome())}\n`);
  console.log('Configured project runtime storage on the workspace volume.');
}
